class Cdp{
 constructor(url){this.url=url;this.ws=null;this.id=1;this.pending=new Map();this.requests=[]}
 async connect(){this.ws=new WebSocket(this.url);await new Promise((r,j)=>{const t=setTimeout(()=>j(new Error('ws timeout')),15000);this.ws.addEventListener('open',()=>{clearTimeout(t);r()},{once:true});this.ws.addEventListener('error',j,{once:true})});this.ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.method==='Network.requestWillBeSent')this.requests.push({url:m.params.request.url,method:m.params.request.method});if(!m.id)return;const p=this.pending.get(m.id);if(!p)return;this.pending.delete(m.id);m.error?p.j(new Error(m.error.message)):p.r(m.result)});for(const x of ['Page.enable','Runtime.enable','Network.enable'])await this.send(x);await this.send('Emulation.setLocaleOverride',{locale:'ko-KR'});await this.send('Page.addScriptToEvaluateOnNewDocument',{source:`(()=>{const nativeFetch=window.fetch.bind(window);window.__qaBlocked={analytics:0,writes:0};window.fetch=(input,init={})=>{const url=typeof input==='string'?input:(input&&input.url)||'';const method=String(init.method||(input&&input.method)||'GET').toUpperCase();if(url.includes('/functions/v1/decision-intake')){window.__qaBlocked.analytics++;return Promise.reject(new TypeError('blocked analytics'))}if(url.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(method)){window.__qaBlocked.writes++;return Promise.reject(new TypeError('blocked write'))}return nativeFetch(input,init)}})();`})}
 send(method,params={}){const id=this.id++;return new Promise((r,j)=>{this.pending.set(id,{r,j});this.ws.send(JSON.stringify({id,method,params}))})}
 async eval(expr){const x=await this.send('Runtime.evaluate',{expression:expr,returnByValue:true,awaitPromise:true});if(x.exceptionDetails)throw new Error(x.exceptionDetails.exception?.description??x.exceptionDetails.text);return x.result?.value}
 async wait(expr,label,ms=40000){const end=Date.now()+ms;while(Date.now()<end){if(await this.eval(`Boolean(${expr})`).catch(()=>false))return;await sleep(100)}throw new Error(`timeout ${label}`)}
 async nav(url){await this.send('Page.navigate',{url});await this.wait(`document.readyState==='complete'`,'ready');await this.wait(`document.querySelector('#root')&&document.body.innerText.length`,'root');await this.eval('document.fonts?.ready');await sleep(250)}
 async shot(name){await this.eval('document.fonts?.ready');await sleep(100);const x=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false});writeFileSync(`${OUT}/${name}`,Buffer.from(x.data,'base64'))}
 close(){try{this.ws?.close()}catch{}}
}
let n=0
async function launch(width,height){const chrome='/usr/bin/google-chrome';assert.ok(existsSync(chrome));const port=14800+(process.pid%80)+n++*40,dir=`/tmp/pr39-compare-final-${process.pid}-${n}`;rmSync(dir,{recursive:true,force:true});const proc=spawn(chrome,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--disable-cache',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'});for(let i=0;i<200;i++){try{const pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json(),p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(!p)throw 0;const c=new Cdp(p.webSocketDebuggerUrl);await c.connect();await c.send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:true,screenWidth:width,screenHeight:height});await c.send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:5});return{c,proc,dir}}catch{}await sleep(100)}throw new Error('chrome launch timeout')}
async function cleanup(h){h.c.close();h.proc.kill('SIGTERM');await sleep(100);if(h.proc.exitCode==null)h.proc.kill('SIGKILL');try{rmSync(h.dir,{recursive:true,force:true})}catch{}}
const state=c=>c.eval(`(()=>{const r=sessionStorage.getItem(${q(STORAGE)});return r?JSON.parse(r).state:null})()`)
const stable=s=>({currentProductId:s.currentProductId,variantSelection:s.variantSelection,compareIds:s.compareIds,compareOpen:s.compareOpen,compareTab:s.compareTab})

async function pointer(c,selector,match=null){const p=await c.eval(`(()=>{const xs=[...document.querySelectorAll(${q(selector)})],b=${match?`xs.find(x=>x.textContent.includes(${q(match)}))`:'xs[0]'};if(!b)return null;b.scrollIntoView({block:'center',inline:'nearest'});const r=b.getBoundingClientRect(),x=Math.max(2,Math.min(innerWidth-2,r.left+r.width/2)),y=Math.max(2,Math.min(innerHeight-2,r.top+r.height/2)),hit=document.elementFromPoint(x,y);if(!hit||!(hit===b||b.contains(hit)))return{blocked:true,rect:[r.left,r.top,r.width,r.height],hit:hit?.className||hit?.tagName};window.__trusted=null;b.addEventListener('click',e=>window.__trusted=e.isTrusted,{once:true,capture:true});return{x,y,text:b.textContent.trim()}})()`);assert.ok(p&&!p.blocked,`pointer unavailable ${selector} ${match??''}: ${JSON.stringify(p)}`);await c.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:p.x,y:p.y,pointerType:'mouse'});await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',buttons:1,clickCount:1,pointerType:'mouse'});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',buttons:0,clickCount:1,pointerType:'mouse'});await sleep(140);assert.equal(await c.eval('window.__trusted'),true);return p}
async function typeSearch(c,text){await pointer(c,'.switch-find-search input');await c.send('Input.dispatchKeyEvent',{type:'keyDown',key:'Control',code:'ControlLeft',windowsVirtualKeyCode:17,nativeVirtualKeyCode:17,modifiers:2});await c.send('Input.dispatchKeyEvent',{type:'keyDown',key:'a',code:'KeyA',windowsVirtualKeyCode:65,nativeVirtualKeyCode:65,modifiers:2});await c.send('Input.dispatchKeyEvent',{type:'keyUp',key:'a',code:'KeyA',windowsVirtualKeyCode:65,nativeVirtualKeyCode:65,modifiers:2});await c.send('Input.dispatchKeyEvent',{type:'keyUp',key:'Control',code:'ControlLeft',windowsVirtualKeyCode:17,nativeVirtualKeyCode:17});await c.send('Input.insertText',{text});await c.wait(`document.querySelector('.switch-find-search input')?.value===${q(text)}`,'typed')}
async function key(c,key,code,keyCode,text=''){const x={key,code,windowsVirtualKeyCode:keyCode,nativeVirtualKeyCode:keyCode,...(text?{text,unmodifiedText:text}:{})};await c.send('Input.dispatchKeyEvent',{type:'keyDown',...x});await c.send('Input.dispatchKeyEvent',{type:'keyUp',...x});await sleep(80)}

async function enterResults(c){await c.nav(`${BASE}?view=workspace&mode=switch`);await c.wait(`document.querySelector('.switch-find-search input')`,'search');await c.wait(`!document.body.innerText.includes('제품 목록을 불러오는 중입니다.')`,'catalog');await typeSearch(c,'AATU 연어');await c.wait(`[...document.querySelectorAll('.switch-find-result')].some(x=>x.textContent.includes('AATU')&&x.textContent.includes('연어'))`,'AATU');await pointer(c,'.switch-find-result','연어');await c.wait(`document.querySelector('.switch-current-preview')`,'preview');await pointer(c,'.switch-current-preview .switch-primary-action');await c.wait(`document.querySelectorAll('.switch-sku-option').length>0`,'sku',30000);await pointer(c,'.switch-sku-option','1 kg');await pointer(c,'.switch-step-actions .switch-primary-action');await c.wait(`document.querySelector('.switch-no-change')`,'change');await pointer(c,'.switch-no-change');await pointer(c,'.switch-step-actions .switch-primary-action');await c.wait(`document.querySelector('.switch-current-facts-strip')`,'keep');await pointer(c,'.switch-step-actions .switch-primary-action');await c.wait(`document.querySelector('.switch-results-stage')`,'results');const s=await state(c);assert.equal(s.currentProductId,CTX.current.id);assert.equal(s.variantSelection.variantId,CTX.sku.id);assert.equal(s.noChangeIntent,true);return s}
async function ensureCandidate(c,p){for(let i=0;i<30;i++){if(await c.eval(`[...document.querySelectorAll('.switch-candidate-row')].some(x=>x.querySelector('.switch-candidate-identity strong')?.textContent.trim()===${q(p.name)}&&x.textContent.includes(${q(p.brand)}))`))return;if(!await c.eval(`Boolean(document.querySelector('.load-more'))`))throw new Error(`candidate missing ${p.name}`);await pointer(c,'.load-more')}throw new Error(`candidate load limit ${p.name}`)}
async function addCandidate(c,p){await ensureCandidate(c,p);const pt=await c.eval(`(()=>{const b=[...document.querySelectorAll('.switch-candidate-row')].find(x=>x.querySelector('.switch-candidate-identity strong')?.textContent.trim()===${q(p.name)}&&x.textContent.includes(${q(p.brand)}));b.scrollIntoView({block:'center'});const r=b.getBoundingClientRect();window.__rowTrusted=null;b.addEventListener('click',e=>window.__rowTrusted=e.isTrusted,{once:true,capture:true});return{x:r.left+r.width/2,y:r.top+r.height/2}})()`);await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:pt.x,y:pt.y,button:'left',buttons:1,clickCount:1,pointerType:'mouse'});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:pt.x,y:pt.y,button:'left',buttons:0,clickCount:1,pointerType:'mouse'});await sleep(140);assert.equal(await c.eval('window.__rowTrusted'),true);await c.wait(`document.querySelector('.switch-candidate-inspector h1')?.textContent.trim()===${q(p.name)}`,'inspector');const before=(await state(c)).compareIds.length;await pointer(c,'.switch-inspector-actions .switch-compare-action','비교에 추가');await c.wait(`(()=>{const r=sessionStorage.getItem(${q(STORAGE)});return r&&JSON.parse(r).state.compareIds.length===${before+1}})()`,'added');assert.equal((await state(c)).compareIds.at(-1),p.id);await pointer(c,'.switch-preview-topline button')}
async function openCompare(c,items){for(const p of items)await addCandidate(c,p);assert.deepEqual((await state(c)).compareIds,items.map(p=>p.id));await pointer(c,'.switch-compare-dock > button');await c.wait(`document.querySelector('.compare-stage')`,'compare');await c.wait(`getComputedStyle(document.querySelector('.compare-switch-mobile-overview')).display!=='none'`,'mobile compare');await c.wait(`document.querySelector('.compare-mobile-product-head.is-current')?.textContent.includes('사용 규격 · 1 kg')`,'usage size')}

async function picker(c){return c.eval(`(()=>{const s=document.querySelector('.compare-mobile-candidate-picker>div'),sr=s.getBoundingClientRect(),bs=[...s.querySelectorAll('button')];return{clientWidth:s.clientWidth,scrollWidth:s.scrollWidth,scrollLeft:s.scrollLeft,maxScroll:s.scrollWidth-s.clientWidth,overflowX:getComputedStyle(s).overflowX,buttons:bs.map((b,i)=>{const r=b.getBoundingClientRect(),cs=getComputedStyle(b),left=Math.max(r.left,sr.left),right=Math.min(r.right,sr.right);return{i,id:b.dataset.productId,text:b.textContent.trim(),pressed:b.getAttribute('aria-pressed'),left:r.left,right:r.right,width:r.width,visibleWidth:Math.max(0,right-left),fullyVisible:r.left>=sr.left&&r.right<=sr.right,clientWidth:b.clientWidth,scrollWidth:b.scrollWidth,textOverflow:cs.textOverflow,whiteSpace:cs.whiteSpace}})}})()`)}
async function measure(c){return c.eval(`(()=>{const rect=n=>{const r=n.getBoundingClientRect();return{top:r.top,bottom:r.bottom,left:r.left,right:r.right,width:r.width,height:r.height}},sty=n=>{if(!n)return null;const s=getComputedStyle(n);return{text:n.textContent.trim().replace(/\\s+/g,' '),fontSize:s.fontSize,lineHeight:s.lineHeight,color:s.color,fontWeight:s.fontWeight,textOverflow:s.textOverflow,whiteSpace:s.whiteSpace,clientWidth:n.clientWidth,scrollWidth:n.scrollWidth,clientHeight:n.clientHeight,scrollHeight:n.scrollHeight,rect:rect(n)}};const hs=[...document.querySelectorAll('.compare-mobile-product-head')],cur=hs.find(x=>x.classList.contains('is-current')),can=hs.find(x=>x.classList.contains('is-candidate')),cs=cur?[...cur.querySelectorAll(':scope>small')]:[],xs=can?[...can.querySelectorAll(':scope>small')]:[],rows=[...document.querySelectorAll('.compare-mobile-overview-row')],unknown=[...document.querySelectorAll('.compare-mobile-pair>div>div')].find(x=>/미확인|확인된 값 없음|공식 표기 미확인/.test(x.textContent)),header=document.querySelector('.compare-header'),scope=document.querySelector('.compare-scope-note'),tabs=document.querySelector('.compare-tabs'),pick=document.querySelector('.compare-mobile-candidate-picker'),grid=document.querySelector('.compare-mobile-head-grid'),first=rows[0],hrs=hs.map(rect);return{viewport:{width:innerWidth,height:innerHeight,scrollY,docClientWidth:document.documentElement.clientWidth,docScrollWidth:document.documentElement.scrollWidth,horizontalOverflow:document.documentElement.scrollWidth-document.documentElement.clientWidth},styles:{pickerLabel:sty(document.querySelector('.compare-mobile-candidate-picker>span')),pickerButton:sty(document.querySelector('.compare-mobile-candidate-picker button[aria-pressed="true"]')),currentRole:sty(cur?.querySelector(':scope>span')),currentBrand:sty(cur?.querySelector('.compare-mobile-product-brand')),currentName:sty(cur?.querySelector(':scope>strong')),currentUsage:sty(cs[1]),currentSale:sty(cs[2]),candidateBrand:sty(can?.querySelector('.compare-mobile-product-brand')),candidateName:sty(can?.querySelector(':scope>strong')),candidateSale:sty(xs[1]),rowLabel:sty(document.querySelector('.compare-mobile-row-label')),currentValue:sty(document.querySelector('.compare-mobile-pair>div:first-child>div')),candidateValue:sty(document.querySelector('.compare-mobile-pair>div:last-child>div')),unknownValue:sty(unknown)},layout:{header:rect(header),scope:rect(scope),tabs:rect(tabs),picker:rect(pick),headGrid:rect(grid),firstRow:rect(first),firstRowTop:first.getBoundingClientRect().top,fullyVisibleRows:rows.filter(x=>{const r=x.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight}).length,intersectingRows:rows.filter(x=>{const r=x.getBoundingClientRect();return r.bottom>0&&r.top<innerHeight}).length,totalRows:rows.length,pairOverlap:hrs.length===2?Math.max(0,hrs[0].right-hrs[1].left):null},rowLabels:rows.map(x=>x.querySelector('.compare-mobile-row-label')?.textContent.trim()),cells:[...document.querySelectorAll('.compare-mobile-pair>div>div')].map(sty)}})()`)}

async function swipe(c){const before=await picker(c),box=await c.eval(`(()=>{const n=document.querySelector('.compare-mobile-candidate-picker>div'),r=n.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2}})()`);let error=null;try{await c.send('Input.synthesizeScrollGesture',{x:box.x,y:box.y,xDistance:-Math.max(120,Math.min(700,before.maxScroll+60)),yDistance:0,speed:800,gestureSourceType:'touch'});await sleep(500)}catch(e){error=String(e)}const after=await picker(c);return{before:before.scrollLeft,after:after.scrollLeft,delta:after.scrollLeft-before.scrollLeft,maxScroll:before.maxScroll,error,lastVisibleWidth:after.buttons.at(-1)?.visibleWidth??0,lastFullyVisible:after.buttons.at(-1)?.fullyVisible??false}}
async function clickVisiblePicker(c,index){const p=await c.eval(`(()=>{const s=document.querySelector('.compare-mobile-candidate-picker>div'),b=s.querySelectorAll('button')[${index}],sr=s.getBoundingClientRect(),r=b.getBoundingClientRect(),l=Math.max(sr.left,r.left),rr=Math.min(sr.right,r.right),t=Math.max(sr.top,r.top),bb=Math.min(sr.bottom,r.bottom);if(rr-l<3||bb-t<3)return null;const x=(l+rr)/2,y=(t+bb)/2,hit=document.elementFromPoint(x,y);if(!hit||!(hit===b||b.contains(hit)))return null;window.__pickerClick=null;b.addEventListener('click',e=>window.__pickerClick=e.isTrusted,{once:true,capture:true});return{x,y,visibleWidth:rr-l,buttonWidth:r.width}})()`);if(!p)return{accessible:false};await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',buttons:1,clickCount:1,pointerType:'mouse'});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',buttons:0,clickCount:1,pointerType:'mouse'});await sleep(120);return{accessible:true,trusted:await c.eval('window.__pickerClick'),...p,selected:await c.eval(`document.querySelectorAll('.compare-mobile-candidate-picker button')[${index}]?.getAttribute('aria-pressed')`)}}
async function keyboardLast(c){await c.eval(`document.querySelector('.compare-mobile-candidate-picker>div').scrollLeft=0`);await sleep(50);const first=await c.eval(`(()=>{const b=document.querySelector('.compare-mobile-candidate-picker button'),r=b.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2}})()`);await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:first.x,y:first.y,button:'left',buttons:1,clickCount:1,pointerType:'mouse'});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:first.x,y:first.y,button:'left',buttons:0,clickCount:1,pointerType:'mouse'});await sleep(80);if(!await c.eval(`document.activeElement===document.querySelector('.compare-mobile-candidate-picker button')`))await c.eval(`document.querySelector('.compare-mobile-candidate-picker button').focus()`);const count=await c.eval(`document.querySelectorAll('.compare-mobile-candidate-picker button').length`);let tabs=0;while(tabs<count+3){const idx=await c.eval(`[...document.querySelectorAll('.compare-mobile-candidate-picker button')].indexOf(document.activeElement)`);if(idx===count-1)break;await key(c,'Tab','Tab',9);tabs++}assert.equal(await c.eval(`[...document.querySelectorAll('.compare-mobile-candidate-picker button')].indexOf(document.activeElement)`),count-1);const before=await picker(c);await c.eval(`(()=>{window.__pickerKey=null;document.activeElement.addEventListener('keydown',e=>window.__pickerKey={key:e.key,isTrusted:e.isTrusted},{once:true,capture:true})})()`);await key(c,'Enter','Enter',13,'\r');const ev=await c.eval('window.__pickerKey');assert.equal(ev?.isTrusted,true);assert.equal(ev?.key,'Enter');return{tabs,event:ev,beforeEnter:before,afterEnter:await picker(c)}}
async function net(c){const writes=c.requests.filter(r=>r.url.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(r.method)),analytics=c.requests.filter(r=>r.url.includes('/functions/v1/decision-intake')),nonRead=c.requests.filter(r=>!['GET','HEAD','OPTIONS'].includes(r.method)),blocked=await c.eval('window.__qaBlocked');assert.equal(writes.length,0);assert.equal(analytics.length,0);assert.equal(nonRead.length,0);assert.deepEqual(blocked,{analytics:0,writes:0});return{gets:c.requests.filter(r=>r.method==='GET').length,writes:0,analytics:0,nonRead:0,blocked}}

async function run(width,height,items,prefix){const h=await launch(width,height),c=h.c,r={viewport:`${width}x${height}`,items};try{await enterResults(c);await openCompare(c,items);r.initialState=stable(await state(c));r.initialPicker=await picker(c);r.initialMeasure=await measure(c);await c.shot(`${prefix}-initial.png`);r.swipe=await swipe(c);r.pointerLast=await clickVisiblePicker(c,items.length-1);r.keyboardLast=await keyboardLast(c);r.afterKeyboardState=stable(await state(c));assert.deepEqual(r.afterKeyboardState,r.initialState);r.pointerAfterKeyboard=await clickVisiblePicker(c,items.length-1);r.afterPointerState=stable(await state(c));assert.deepEqual(r.afterPointerState,r.initialState);r.finalPicker=await picker(c);r.finalMeasure=await measure(c);await c.shot(`${prefix}-${items.length===2?'second':'last'}.png`);r.network=await net(c);return r}finally{await cleanup(h)}}

const report={productSha:PRODUCT_SHA,page:BASE,context:CTX,status:'running'}
try{report.mobile360=await run(360,844,CTX.two,'360-compare');report.mobile390=await run(390,900,CTX.five,'390-compare');const unknown=report.mobile390.initialMeasure.styles.unknownValue;assert.ok(unknown,'unknown display missing');const long=report.mobile390.finalMeasure.styles.candidateName;assert.equal(long.text,CTX.five[4].name);assert.notEqual(long.textOverflow,'ellipsis');assert.ok(long.scrollWidth<=long.clientWidth+1);assert.ok(long.scrollHeight<=long.clientHeight+1);report.status='pass';writeFileSync(`${OUT}/report.json`,JSON.stringify(report,null,2));console.log('COMPARE_READABILITY_PASS',JSON.stringify({current:CTX.current,sku:CTX.sku,two:CTX.two,five:CTX.five,m360:{picker:report.mobile360.initialPicker,swipe:report.mobile360.swipe,keyboard:report.mobile360.keyboardLast,layout:report.mobile360.initialMeasure.layout},m390:{picker:report.mobile390.initialPicker,swipe:report.mobile390.swipe,keyboard:report.mobile390.keyboardLast,layout:report.mobile390.initialMeasure.layout,styles:report.mobile390.finalMeasure.styles,unknown}}))}catch(e){report.status='fail';report.error=String(e?.stack||e);writeFileSync(`${OUT}/report.json`,JSON.stringify(report,null,2));throw e}
